sys_script.script:
(function executeRule(current, previous) {
    // Auto-generate Booking Number on Insert
    if (current.operation() == 'insert' && !current.getValue('booking_number')) {
        var lastGr = new GlideRecord('x_1877508_metro_0_metro_booking');
        lastGr.orderByDesc('sys_created_on');
        lastGr.setLimit(1);
        lastGr.query();

        var nextNum = 1;
        if (lastGr.next()) {
            var lastBkNum = lastGr.getValue('booking_number') || '';
            var numPart = parseInt(lastBkNum.replace('BK', ''), 10);
            if (!isNaN(numPart)) {
                nextNum = numPart + 1;
            }
        }

        var paddedNum = ('00000' + nextNum).slice(-5);
        current.setValue('booking_number', 'BK' + paddedNum);
    }

    // Fare calculation based on route distance
    var sourceStation = current.getValue('source_station');
    var destStation = current.getValue('destination_station');
    var passengerCount = parseInt(current.getValue('passenger_count'), 10) || 1;

    if (sourceStation && destStation) {
        // Find route distance
        var routeGr = new GlideRecord('x_1877508_metro_0_metro_routes');
        routeGr.addQuery('source_station', sourceStation);
        routeGr.addQuery('destination_station', destStation);
        routeGr.query();

        var distanceKm = 0;
        if (routeGr.next()) {
            distanceKm = parseFloat(routeGr.getValue('distance_km')) || 0;
        } else {
            // Try reverse route
            var reverseGr = new GlideRecord('x_1877508_metro_0_metro_routes');
            reverseGr.addQuery('source_station', destStation);
            reverseGr.addQuery('destination_station', sourceStation);
            reverseGr.query();
            if (reverseGr.next()) {
                distanceKm = parseFloat(reverseGr.getValue('distance_km')) || 0;
            }
        }

        if (distanceKm > 0) {
            var fare = distanceKm * 2 * passengerCount;
            if (fare < 5) {
                fare = 5;
            }
            current.setValue('fare_amount', fare);
        }
    }
})(current, previous);
